function validate([tasks]) {
  if (tasks.length < 1 || tasks.length > 100000) return 'tasks needs 1 to 10^5 entries.';
  for (const task of tasks) {
    if (!Array.isArray(task) || task.length !== 2) return 'Each task is a pair [actual, minimum].';
    const [actual, minimum] = task;
    if (!Number.isInteger(actual) || !Number.isInteger(minimum)) return 'Energies are whole numbers.';
    if (actual < 1 || actual > minimum || minimum > 10000) return 'Each task needs 1 <= actual <= minimum <= 10^4.';
  }
  return null;
}

