function minimumEffort(tasks) {
  tasks.sort((a, b) => (b[1] - b[0]) - (a[1] - a[0]));
  let answer = 0;
  let energy = 0;
  for (const [actual, minimum] of tasks) {
    if (energy < minimum) {
      answer += minimum - energy;
      energy = minimum;
    }
    energy -= actual;
  }
  return answer;
}

