function minimumEffort(tasks) {
  // Try every order; an order needs, at each task, its minimum plus everything spent before it.
  const n = tasks.length, used = new Array(n).fill(false);
  let best = Infinity;
  const search = (spent, need, done) => {
    if (need >= best) return;
    if (done === n) { best = need; return; }
    for (let i = 0; i < n; i++) {
      if (used[i]) continue;
      used[i] = true;
      search(spent + tasks[i][0], Math.max(need, spent + tasks[i][1]), done + 1);
      used[i] = false;
    }
  };
  search(0, 0, 0);
  return best;
}

