function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  if (size === 'large') {
    const n = 2000;
    return [Array.from({ length: n }, () => { const minimum = 1 + pick(10000); return [1 + pick(minimum), minimum]; })];
  }
  const n = 1 + pick(7);
  const top = [3, 10, 20][pick(3)];
  return [Array.from({ length: n }, () => { const minimum = 1 + pick(top); return [1 + pick(minimum), minimum]; })];
}
